    "source": "https://finstack_quant.dev/schemas/instrument/1/fixed_income/structured_credit.schema.json#/$defs/PenaltyStep/properties/pct",
    "description": "Premium in percent of the prepaid balance (`3.0` = 3%).",
    "format": "double"
